// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamSettlementAdmission.sol";
import "../../interfaces/stream/revenue/IStreamDirectPrimarySaleReceipt.sol";
import "../../interfaces/stream/mint/IStreamMintReads.sol";

/// @notice Live canonical admission for the original direct products, including retained auctions.
/// @dev Uses exact-code fixed-buffer infrastructure reads, as in the original settlement admission.
library StreamDirectPrimaryAdmission {
    error DirectPrimaryDependency(address target);
    error DirectPrimaryNotAdmitted(address adapter);
    error DirectPrimaryOriginInvalid(bytes32 authorizationId);

    function capture(
        StreamDirectPrimarySaleTypes.Bindings memory bindings,
        address registry,
        bytes32 registryCodeHash
    ) public view returns (uint64 createdAt, uint64 revision) {
        _bindings(bindings, registry, registryCodeHash);
        StreamSettlementAdmission.ModuleFacts memory facts = _record(registry);
        if (facts.status != 1 || block.timestamp == 0 || block.timestamp > type(uint64).max) {
            revert DirectPrimaryNotAdmitted(address(this));
        }
        return (uint64(block.timestamp), facts.revision);
    }

    function requireReceipt(
        StreamDirectPrimarySaleTypes.Bindings memory bindings,
        address registry,
        bytes32 registryCodeHash,
        bytes32 authorizationId,
        StreamDirectPrimarySaleTypes.Receipt memory receipt
    ) public view {
        _bindings(bindings, registry, registryCodeHash);
        StreamSettlementAdmission.ModuleFacts memory facts = _record(registry);
        bool auction = bindings.productKind == StreamDirectPrimarySaleTypes.ENGLISH_AUCTION;
        if (
            receipt.createdAt == 0 || receipt.createdAt > block.timestamp
                || receipt.createdAt < facts.registeredAt || receipt.registryRevision == 0
                || receipt.registryRevision > facts.revision
                || (!auction
                    && (facts.status != 1
                        || receipt.createdAt != block.timestamp
                        || receipt.registryRevision != facts.revision))
                || (facts.status == 2
                    && (!auction
                        || receipt.createdAt >= facts.statusUpdatedAt
                        || receipt.registryRevision >= facts.revision))
        ) revert DirectPrimaryNotAdmitted(address(this));
        if (
            authorizationId == 0 || receipt.authorizationDigest == 0 || receipt.collectionId == 0
                || receipt.tokenId == 0 || receipt.operationRoot == 0 || receipt.operationId == 0
                || receipt.boundMintPolicyHash == 0 || receipt.expectedPrimaryPolicyHash == 0
                || receipt.profileId == 0 || receipt.wallet == address(0)
                || receipt.payer == address(0) || receipt.beneficiary == address(0)
                || receipt.amount == 0
                || (bindings.productKind == StreamDirectPrimarySaleTypes.ERC20_FIXED_PRICE
                        ? receipt.asset == address(0)
                        : receipt.asset != address(0))
                || _word(
                        bindings.mintManager,
                        abi.encodeCall(
                            IStreamMintReads.isOperationRootUsed, (receipt.operationRoot)
                        )
                    ) != 1
                || _word(
                        bindings.mintManager,
                        abi.encodeCall(IStreamMintReads.isAuthorizationUsed, (authorizationId))
                    ) != 1
        ) revert DirectPrimaryOriginInvalid(authorizationId);
    }

    function _bindings(
        StreamDirectPrimarySaleTypes.Bindings memory bindings,
        address registry,
        bytes32 registryCodeHash
    ) private view {
        StreamSettlementAdmission.requireRegistry(
            bindings.core, bindings.coreCodeHash, registry, registryCodeHash
        );
        if (
            block.chainid != bindings.deploymentChainId
                || !StreamSettlementAdmission.isContract(bindings.mintManager)
                || bindings.mintManager.codehash != bindings.mintManagerCodeHash
                || _word(bindings.mintManager, abi.encodeCall(IStreamMintReads.core, ()))
                    != uint160(bindings.core)
                || _word(bindings.mintManager, abi.encodeCall(IStreamMintReads.moduleRegistry, ()))
                    != uint160(registry)
        ) revert DirectPrimaryDependency(bindings.mintManager);
    }

    function _record(address registry)
        private
        view
        returns (StreamSettlementAdmission.ModuleFacts memory facts)
    {
        bytes memory data = abi.encodeCall(IStreamModuleRegistry.moduleRecord, (address(this)));
        uint256[14] memory w;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), registry, add(data, 32), mload(data), w, 448)
            size := returndatasize()
        }
        bytes4 id = type(IStreamDirectPrimarySaleReceipt).interfaceId;
        if (
            !ok || size < 448 || w[0] != 32 || (w[1] != 1 && w[1] != 2)
                || bytes32(w[2]) != StreamDirectPrimarySaleTypes.MODULE_TYPE
                || bytes32(w[3]) != StreamDirectPrimarySaleTypes.MODULE_VERSION
                || w[4] != uint256(uint32(id)) << 224 || w[5] > type(uint32).max
                || bytes32(w[6]) != address(this).codehash || w[7] == 0 || w[8] == 0 || w[9] != 384
                || w[10] == 0 || w[10] > block.timestamp || w[10] > type(uint64).max
                || w[11] < w[10] || w[11] > block.timestamp || w[11] > type(uint64).max
                || w[12] == 0 || w[12] > type(uint64).max || w[13] > size - 448
                || size - 448 != ((w[13] + 31) / 32) * 32
                || _word(address(this), abi.encodeCall(IERC165.supportsInterface, (id))) != 1
                || _word(
                        address(this),
                        abi.encodeCall(IERC165.supportsInterface, (bytes4(0x01ffc9a7)))
                    ) != 1
                || _word(
                        address(this),
                        abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff)))
                    ) != 0
        ) revert DirectPrimaryNotAdmitted(address(this));
        facts = StreamSettlementAdmission.ModuleFacts(
            uint8(w[1]), uint64(w[10]), uint64(w[11]), uint64(w[12])
        );
    }

    function _word(address target, bytes memory data) private view returns (uint256 value) {
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            value := mload(0)
        }
        if (!ok || size != 32) revert DirectPrimaryDependency(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamDirectPrimaryAdmission.sol";
import "./StreamDirectPrimarySaleHash.sol";
import "./StreamDirectPrimarySaleFloorCall.sol";

/// @notice Local immutable paid witnesses shared by the three original direct sale products.
abstract contract StreamDirectPrimaryReceipts is IStreamDirectPrimarySaleReceipt {
    address private immutable _directCore;
    bytes32 private immutable _directCoreCodeHash;
    address private immutable _directMintManager;
    bytes32 private immutable _directMintManagerCodeHash;
    uint256 private immutable _directChainId;
    bytes32 private immutable _directProductKind;
    address private immutable _directRegistry;
    bytes32 private immutable _directRegistryCodeHash;
    mapping(bytes32 => StreamDirectPrimarySaleTypes.Receipt) private _directReceipts;

    error InvalidDirectPrimaryConfiguration();
    error DirectPrimaryReceiptAlreadyRecorded(bytes32 authorizationId);

    constructor(address core_, address manager_, bytes32 productKind_) {
        if (
            !StreamSettlementAdmission.isContract(core_)
                || !StreamSettlementAdmission.isContract(manager_)
                || address(IStreamMintReads(manager_).core()) != core_
                || (productKind_ != StreamDirectPrimarySaleTypes.NATIVE_FIXED_PRICE
                    && productKind_ != StreamDirectPrimarySaleTypes.ERC20_FIXED_PRICE
                    && productKind_ != StreamDirectPrimarySaleTypes.ENGLISH_AUCTION)
        ) revert InvalidDirectPrimaryConfiguration();
        address registry = address(IStreamMintReads(manager_).moduleRegistry());
        if (!StreamSettlementAdmission.isContract(registry)) {
            revert InvalidDirectPrimaryConfiguration();
        }
        _directCore = core_;
        _directCoreCodeHash = core_.codehash;
        _directMintManager = manager_;
        _directMintManagerCodeHash = manager_.codehash;
        _directChainId = block.chainid;
        _directProductKind = productKind_;
        _directRegistry = registry;
        _directRegistryCodeHash = registry.codehash;
    }

    function directPrimaryBindings()
        public
        view
        override
        returns (StreamDirectPrimarySaleTypes.Bindings memory)
    {
        return StreamDirectPrimarySaleTypes.Bindings(
            _directCore,
            _directCoreCodeHash,
            _directMintManager,
            _directMintManagerCodeHash,
            _directChainId,
            _directProductKind
        );
    }

    function directPrimarySaleReceipt(bytes32 authorizationId)
        public
        view
        override
        returns (StreamDirectPrimarySaleTypes.Receipt memory)
    {
        return _directReceipts[authorizationId];
    }

    function directPrimarySaleReceiptHash(bytes32 authorizationId)
        public
        view
        override
        returns (bytes32)
    {
        StreamDirectPrimarySaleTypes.Receipt memory receipt = _directReceipts[authorizationId];
        if (receipt.amount == 0) return bytes32(0);
        return StreamDirectPrimarySaleHash.receiptHash(
            directPrimaryBindings(), address(this), authorizationId, receipt
        );
    }

    function _captureDirectPrimaryAdmission()
        internal
        view
        returns (uint64 createdAt, uint64 registryRevision)
    {
        return StreamDirectPrimaryAdmission.capture(
            directPrimaryBindings(), _directRegistry, _directRegistryCodeHash
        );
    }

    /// @dev Call only after original funding, mint/transfer and final callback-sensitive checks.
    /// The receipt is readable by the floor in this call; any later revert removes every effect.
    function _recordDirectPrimarySale(
        bytes32 authorizationId,
        StreamDirectPrimarySaleTypes.Receipt memory receipt
    ) internal {
        if (_directReceipts[authorizationId].amount != 0) {
            revert DirectPrimaryReceiptAlreadyRecorded(authorizationId);
        }
        StreamDirectPrimaryAdmission.requireReceipt(
            directPrimaryBindings(),
            _directRegistry,
            _directRegistryCodeHash,
            authorizationId,
            receipt
        );
        _directReceipts[authorizationId] = receipt;
        StreamDirectPrimarySaleFloorCall.record(_directCore, authorizationId);
        emit DirectPrimarySaleRecorded(
            authorizationId,
            StreamDirectPrimarySaleHash.receiptHash(
                directPrimaryBindings(), address(this), authorizationId, receipt
            ),
            receipt.tokenId,
            receipt,
            1
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/core/IStreamCoreConservationFloor.sol";
import "../../interfaces/stream/metadata/IStreamDirectPrimaryConservationFloor.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";

/// @notice Fixed original floor call after genuine DIRECT payment and mint/transfer completion.
library StreamDirectPrimarySaleFloorCall {
    uint256 private constant READ_GAS = 100000;
    uint256 private constant RETURN_RESERVE = 100000;
    bytes32 private constant CALL_GAS = keccak256("6529STREAM_GGP_CONSERVATION_FLOOR_CALL_GAS");

    error DirectSaleFloorBindingUnavailable();
    error DirectSaleFloorCallFailed(address ledger, bytes4 cause);
    error DirectSaleFloorInsufficientGas(uint256 cap);

    function record(address core, bytes32 authorizationId) public {
        _admit(READ_GAS);
        bytes memory data = abi.encodeCall(IStreamCoreConservationFloor.conservationFloor, ());
        uint256[2] memory binding;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(READ_GAS, core, add(data, 32), mload(data), binding, 64)
            size := returndatasize()
        }
        if (!ok || size != 64 || binding[0] == 0 || binding[0] > type(uint160).max) {
            revert DirectSaleFloorBindingUnavailable();
        }
        address ledger = address(uint160(binding[0]));
        if (ledger.code.length == 0 || ledger.codehash != bytes32(binding[1])) {
            revert DirectSaleFloorBindingUnavailable();
        }
        _admit(READ_GAS);
        data = abi.encodeCall(IStreamGasParameterHost.gasParameter, (CALL_GAS));
        uint256 cap;
        assembly ("memory-safe") {
            ok := staticcall(READ_GAS, ledger, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            cap := mload(0)
        }
        if (!ok || size != 32 || cap == 0 || cap > type(uint256).max / 64) {
            revert DirectSaleFloorBindingUnavailable();
        }
        data = abi.encodeCall(
            IStreamDirectPrimaryConservationFloor.recordDirectPrimarySale, (authorizationId)
        );
        _admit(cap);
        bytes32 returned;
        assembly ("memory-safe") {
            ok := call(cap, ledger, 0, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            returned := mload(0)
        }
        if (!ok || size != 32 || returned == 0) {
            revert DirectSaleFloorCallFailed(ledger, bytes4(returned));
        }
    }

    function _admit(uint256 cap) private view {
        if (gasleft() <= cap + cap / 63 + RETURN_RESERVE + 3300) {
            revert DirectSaleFloorInsufficientGas(cap);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/StreamDirectPrimarySaleTypes.sol";

/// @notice Domain-separated identities for original DIRECT receipts, without universal aliases.
library StreamDirectPrimarySaleHash {
    bytes32 private constant KEY_DOMAIN = keccak256("6529STREAM_DIRECT_PRIMARY_SALE_KEY_V1");
    bytes32 private constant RECEIPT_DOMAIN =
        keccak256("6529STREAM_DIRECT_PRIMARY_SALE_RECEIPT_V1");

    function settlementKey(
        StreamDirectPrimarySaleTypes.Bindings memory bindings,
        address adapter,
        bytes32 authorizationId
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                KEY_DOMAIN,
                bindings.deploymentChainId,
                bindings.core,
                adapter,
                bindings.productKind,
                authorizationId
            )
        );
    }

    function receiptHash(
        StreamDirectPrimarySaleTypes.Bindings memory bindings,
        address adapter,
        bytes32 authorizationId,
        StreamDirectPrimarySaleTypes.Receipt memory receipt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                RECEIPT_DOMAIN,
                bindings.deploymentChainId,
                bindings.core,
                adapter,
                bindings.productKind,
                authorizationId,
                receipt
            )
        );
    }
}

