pragma solidity ^0.8.19;

import "./IStreamSplitWallet.sol";

/// @notice Interface for outside-Core primary revenue assignment resolution.
interface IStreamRevenueResolver {
    /// @notice Template entry before dynamic account sources are materialized.
    struct PrimaryTemplateEntry {
        address account;
        bytes32 accountSource;
        uint32 sharePpm;
        bytes32 labelId;
    }

    /// @notice Resolved assignment selected for a primary sale context.
    struct ResolvedPrimaryAssignment {
        bool exists;
        uint8 scope;
        uint256 scopeId;
        uint8 assignmentType;
        bytes32 profileId;
        bytes32 templateId;
        bytes32 policyHash;
        bytes32 assignmentHash;
        bool frozen;
    }

    /// @notice Reverts when a revenue class is zero.
    error InvalidRevenueClass(bytes32 revenueClass);
    /// @notice Reverts when an assignment scope is unsupported or has invalid identity.
    error InvalidAssignmentScope(uint8 scope, uint256 scopeId);
    /// @notice Reverts when an assignment type is unsupported.
    error InvalidAssignmentType(uint8 assignmentType);
    /// @notice This implementation supports only the canonical zero no-loosening policy.
    error InvalidPrimaryPolicyHash();
    error InvalidPrimaryResolverConfiguration();
    error InvalidPrimaryArtistRegistry(address selected);
    error InvalidPrimaryCollection(uint256 collectionId);
    error InvalidPrimaryTokenIdentity(uint256 tokenId, uint256 suppliedCollectionId);
    error PrimaryArtistConsentRequired(uint256 collectionId);
    error UnsupportedArtistPrimaryAssignment(uint256 collectionId);
    /// @notice Reverts when a split profile is unknown or lacks a verified wallet.
    error UnverifiedSplitProfile(bytes32 profileId);
    /// @notice Reverts when a template entry is invalid.
    error InvalidPrimaryTemplateEntry(uint256 index);
    /// @notice Reverts when template shares do not sum to the share denominator.
    error InvalidPrimaryTemplateTotal(uint256 totalSharePpm);
    /// @notice Reverts when the template does not exist.
    error UnknownPrimaryTemplate(bytes32 templateId);
    /// @notice Reverts when a dynamic account source is unsupported.
    error UnsupportedAccountSource(bytes32 accountSource);
    /// @notice Reverts when a dynamic account source materializes to zero.
    error InvalidMaterializedAccount(bytes32 accountSource);
    error MissingArtistMaterializationContext();
    error UnresolvableArtistBeneficiary(uint256 collectionId);
    error InsufficientArtistBeneficiaryGas(uint256 requiredCap, uint256 available);
    /// @notice Reverts when a frozen assignment would be changed or cleared.
    error PrimaryAssignmentFrozen(bytes32 revenueClass, uint8 scope, uint256 scopeId);
    /// @notice Reverts when freezing a missing assignment.
    error PrimaryAssignmentMissing(bytes32 revenueClass, uint8 scope, uint256 scopeId);

    /// @notice Emitted once when a primary split template is created.
    event PrimaryTemplateCreated(
        bytes32 indexed templateId,
        bytes32 indexed entriesHash,
        bytes32 indexed metadataURIHash,
        uint16 schemaVersion,
        uint16 templateVersion
    );
    /// @notice Emitted for each canonical template entry.
    event PrimaryTemplateEntryRecorded(
        bytes32 indexed templateId,
        uint16 indexed index,
        address indexed account,
        bytes32 accountSource,
        uint32 sharePpm,
        bytes32 labelId
    );
    /// @notice Emitted when a primary assignment is set.
    event PrimaryAssignmentSet(
        bytes32 indexed revenueClass,
        uint8 indexed scope,
        uint256 indexed scopeId,
        uint8 assignmentType,
        bytes32 profileId,
        bytes32 templateId,
        bytes32 policyHash,
        bytes32 assignmentHash,
        address admin
    );
    /// @notice Emitted when a primary assignment is cleared.
    event PrimaryAssignmentCleared(
        bytes32 indexed revenueClass,
        uint8 indexed scope,
        uint256 indexed scopeId,
        bytes32 previousAssignmentHash,
        address admin
    );
    /// @notice Emitted when a primary assignment is frozen against later mutation.
    event PrimaryAssignmentFrozenEvent(
        bytes32 indexed revenueClass,
        uint8 indexed scope,
        uint256 indexed scopeId,
        bytes32 previousAssignmentHash,
        bytes32 frozenAssignmentHash,
        address admin
    );
    /// @notice Emitted when a dynamic template is materialized into a fixed split profile.
    event PrimaryTemplateMaterialized(
        bytes32 indexed templateId,
        bytes32 indexed profileId,
        address indexed wallet,
        bytes32 entriesHash,
        bytes32 metadataURIHash,
        address salePoster
    );

    /// @notice Current-read witness for a public cache operation, never official sale evidence.
    event CollectionTemplateMaterialized(
        bytes32 indexed templateId,
        bytes32 indexed profileId,
        uint256 indexed collectionId,
        uint16 schemaVersion,
        bytes32 artistId,
        address payoutAccount,
        bytes32 designationRecordHash,
        address wallet,
        bytes32 entriesHash,
        bool walletDeployed
    );

    /// @notice Default resolver scope.
    function SCOPE_DEFAULT() external pure returns (uint8);
    /// @notice Collection resolver scope.
    function SCOPE_COLLECTION() external pure returns (uint8);
    /// @notice Token resolver scope.
    function SCOPE_TOKEN() external pure returns (uint8);
    /// @notice Fixed split profile assignment type.
    function ASSIGNMENT_TYPE_PROFILE() external pure returns (uint8);
    /// @notice Dynamic primary template assignment type.
    function ASSIGNMENT_TYPE_TEMPLATE() external pure returns (uint8);
    /// @notice Dynamic account source for the poster attached to a sale.
    function ACCOUNT_SOURCE_SALE_POSTER() external pure returns (bytes32);
    function ACCOUNT_SOURCE_COLLECTION_ARTIST() external pure returns (bytes32);
    function ARTIST_LABEL() external pure returns (bytes32);
    function ARTIST_BENEFICIARY_READ_GAS() external pure returns (bytes32);
    /// @notice The split factory used to verify and materialize profiles.
    function splitFactory() external view returns (address);
    /// @notice Permanent Core whose collection and token identity govern this resolver.
    function core() external view returns (address);
    /// @notice Explicit immutable facade pin, required to be Core-selected for assignment writes/resolution.
    function artistRegistry() external view returns (address);
    function coreCodeHash() external view returns (bytes32);
    function artistRegistryCodeHash() external view returns (bytes32);
    /// @notice Returns true for deployment validation.
    function isStreamRevenueResolver() external pure returns (bool);
    /// @notice Creates or reuses a primary split template.
    function createPrimaryTemplate(PrimaryTemplateEntry[] calldata entries, bytes32 metadataURIHash)
        external
        returns (bytes32 templateId);
    /// @notice Sets a fixed-profile primary assignment with zero no-loosening policy.
    /// @dev The current profile closes collection/token mutation at initial artist nomination.
    function setPrimaryProfileAssignment(
        bytes32 revenueClass,
        uint8 scope,
        uint256 scopeId,
        bytes32 profileId,
        bytes32 policyHash
    ) external returns (bytes32 assignmentHash);
    /// @notice Sets a zero-policy dynamic template before artist nomination.
    /// @dev Template writes remain closed after artist nomination. Supported initial templates
    ///      may be configured beforehand; resolving them does not prove recorded artist consent.
    function setPrimaryTemplateAssignment(
        bytes32 revenueClass,
        uint8 scope,
        uint256 scopeId,
        bytes32 templateId,
        bytes32 policyHash
    ) external returns (bytes32 assignmentHash);
    /// @notice Clears a mutable primary assignment.
    function clearPrimaryAssignment(bytes32 revenueClass, uint8 scope, uint256 scopeId) external;
    /// @notice Freezes an existing primary assignment before artist nomination.
    function freezePrimaryAssignment(bytes32 revenueClass, uint8 scope, uint256 scopeId)
        external
        returns (bytes32 frozenAssignmentHash);
    /// @notice Resolves assignments against the pinned, currently Core-selected artist facade.
    /// @dev Nonzero token IDs must match Core's retained collection identity, including burns.
    ///      Artist-bound contexts support explicit collection fixed profiles and the validated
    ///      initial COLLECTION_ARTIST template profile. This read
    ///      exposes current terms; it does not itself assert that artist consent was recorded.
    function resolvePrimaryAssignment(uint256 collectionId, uint256 tokenId, bytes32 revenueClass)
        external
        view
        returns (ResolvedPrimaryAssignment memory assignment);
    /// @notice Materializes a dynamic template into a deterministic split profile.
    function materializePrimaryProfile(bytes32 templateId, address salePoster)
        external
        returns (bytes32 profileId, address wallet, bytes32 entriesHash);
    /// @notice Collection-aware public cache; reads the currently accepted explicit artist payout.
    /// @dev Registration-only returns a predicted wallet, which is not proof of deployment.
    ///      This does not authorize TEMPLATE assignment or a sale; old fixed profiles keep their payees.
    function materializeCollectionPrimaryProfile(
        bytes32 templateId,
        uint256 collectionId,
        address salePoster,
        bool deployWallet
    ) external returns (bytes32 profileId, address wallet, bytes32 entriesHash);
    /// @notice Previews current concrete rights using the same derivation as materialization.
    /// @dev Does not register or deploy; a predicted empty wallet is not an official deposit target.
    function previewCollectionPrimaryProfile(
        bytes32 templateId,
        uint256 collectionId,
        address salePoster
    ) external view returns (bytes32 profileId, address wallet, bytes32 entriesHash);
    /// @notice Returns deterministic template metadata.
    function primaryTemplate(bytes32 templateId)
        external
        view
        returns (bool exists, bytes32 entriesHash, bytes32 metadataURIHash);
    /// @notice Returns the number of canonical entries in a template.
    function primaryTemplateEntryCount(bytes32 templateId) external view returns (uint256);
    /// @notice Returns one canonical template entry.
    function primaryTemplateEntry(bytes32 templateId, uint256 index)
        external
        view
        returns (address account, bytes32 accountSource, uint32 sharePpm, bytes32 labelId);
    /// @notice Computes a zero-policy assignment hash for explicit inputs, not a live selection.
    function primaryAssignmentHash(
        bytes32 revenueClass,
        uint8 scope,
        uint256 scopeId,
        uint8 assignmentType,
        bytes32 profileId,
        bytes32 templateId,
        bytes32 policyHash,
        bool frozen
    ) external view returns (bytes32);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../parameters/IStreamGasParameterHost.sol";

import "./IStreamSplitWallet.sol";
import "./IStreamAssetPolicyRegistry.sol";

/// @notice Interface for creating deterministic split profiles and wallets.
interface IStreamSplitFactory is IStreamGasParameterHost {
    function gasParameterFloor(bytes32 parameterId) external view returns (uint256);
    /// @notice Reverts when two canonical entries use the same account and label.
    error DuplicateSplitEntry(address account, bytes32 labelId);
    /// @notice Reverts when a split profile has zero entries or exceeds the entry limit.
    error InvalidEntryCount(uint256 count);
    /// @notice Reverts when a split entry account is the zero address.
    error InvalidSplitAccount(uint256 index);
    /// @notice Reverts when a split entry share is zero or above the denominator.
    error InvalidSplitShare(uint256 index);
    /// @notice Reverts when split entry shares do not sum to the denominator.
    error InvalidSplitTotal(uint256 totalSharePpm);
    /// @notice Reverts when the factory is initialized with an invalid asset policy registry.
    error InvalidAssetPolicyRegistry(address registry);
    /// @notice Reverts when the deterministic wallet address already has unexpected code.
    error SplitWalletAddressPoisoned(bytes32 profileId, address wallet);
    /// @notice Reverts when a caller asks to deploy a profile that does not exist.
    error UnknownProfile(bytes32 profileId);

    /// @notice Emitted once when a canonical split profile is first created.
    event SplitProfileCreated(
        bytes32 indexed profileId,
        bytes32 indexed entriesHash,
        bytes32 indexed metadataURIHash,
        uint16 schemaVersion,
        uint16 walletVersion,
        address wallet
    );
    /// @notice Emitted for each canonical label-level split entry in a created profile.
    event SplitProfileEntry(
        bytes32 indexed profileId,
        uint16 indexed index,
        address indexed account,
        uint16 schemaVersion,
        uint32 sharePpm,
        bytes32 labelId
    );
    /// @notice Emitted when the factory deploys a split wallet for a profile.
    event SplitWalletDeployed(
        bytes32 indexed profileId,
        address indexed wallet,
        uint16 indexed walletVersion,
        uint16 schemaVersion,
        bytes32 initCodeHash,
        bytes32 runtimeCodeHash
    );
    /// @notice Emitted when the factory records a pre-existing wallet with expected code.
    event SplitWalletDiscovered(
        bytes32 indexed profileId,
        address indexed wallet,
        uint16 indexed walletVersion,
        uint16 schemaVersion,
        bytes32 initCodeHash,
        bytes32 runtimeCodeHash
    );
    /// @notice Emitted once when the factory pins its deployment-wide asset policy registry.
    event AssetPolicyRegistryPinned(address indexed registry);

    /// @notice Domain separator label for profile identifiers.
    function PROFILE_DOMAIN() external pure returns (bytes32);
    /// @notice Split profile schema version.
    function SCHEMA_VERSION() external pure returns (uint16);
    /// @notice Split wallet implementation version.
    function WALLET_VERSION() external pure returns (uint16);
    /// @notice Maximum label-level entries in one profile.
    function MAX_ENTRIES() external pure returns (uint16);
    /// @notice Maximum unique account aggregates in one profile.
    function MAX_UNIQUE_ACCOUNTS() external pure returns (uint16);
    /// @notice Parts-per-million share denominator.
    function SHARE_DENOMINATOR_PPM() external pure returns (uint32);
    /// @notice Deployment-wide asset policy registry pinned for split-wallet ERC-20 support.
    function assetPolicyRegistry() external view returns (IStreamAssetPolicyRegistry);
    /// @notice Returns the wallet creation-code hash used by CREATE2.
    function splitWalletInitCodeHash() external view returns (bytes32);
    /// @notice Returns the wallet runtime-code hash accepted after deployment.
    function splitWalletRuntimeCodeHash() external view returns (bytes32);
    /// @notice Creates or reuses a split profile and deploys its wallet.
    function createProfile(
        IStreamSplitWallet.SplitEntry[] calldata entries,
        bytes32 metadataURIHash
    ) external returns (bytes32 profileId, address wallet);
    /// @notice Registers canonical immutable terms without deploying a wallet.
    /// @dev Repeated canonical registration is idempotent; wallet is the predicted address.
    function registerProfile(
        IStreamSplitWallet.SplitEntry[] calldata entries,
        bytes32 metadataURIHash
    ) external returns (bytes32 profileId, address wallet);
    /// @notice Total profiles ever registered, including those with no deployed wallet.
    function profileCount() external view returns (uint256);
    /// @notice Profile at its immutable zero-based registration index; out of range reverts.
    function profileAt(uint256 index) external view returns (bytes32 profileId);
    /// @notice Predicted address for profileAt(index), regardless of deployment state.
    function walletAt(uint256 index) external view returns (address wallet);
    /// @notice Deploys the wallet for an existing profile.
    function deployWallet(bytes32 profileId) external returns (address wallet);
    /// @notice Returns true when a profile exists.
    function profileExists(bytes32 profileId) external view returns (bool);
    /// @notice Returns true when the profile wallet is deployed with expected code and metadata.
    function splitWalletExists(bytes32 profileId) external view returns (bool);
    /// @notice Returns the metadata URI hash committed by a profile.
    function profileMetadataURIHash(bytes32 profileId) external view returns (bytes32);
    /// @notice Returns the canonical entries hash committed by a profile.
    function profileEntriesHash(bytes32 profileId) external view returns (bytes32);
    /// @notice Returns the deterministic wallet address for a profile.
    function walletFor(bytes32 profileId) external view returns (address);
    /// @notice Computes a profile identifier for entries and metadata.
    function profileIdFor(IStreamSplitWallet.SplitEntry[] calldata entries, bytes32 metadataURIHash)
        external
        view
        returns (bytes32);
    /// @notice Returns the canonical entry count for a profile.
    function profileEntryCount(bytes32 profileId) external view returns (uint256);
    /// @notice Returns one canonical profile entry by index.
    function profileEntry(bytes32 profileId, uint256 index)
        external
        view
        returns (address account, uint32 sharePpm, bytes32 labelId);
    /// @notice Returns the unique account count for a profile.
    function profileUniqueAccountCount(bytes32 profileId) external view returns (uint256);
    /// @notice Returns one unique account and aggregate share by index.
    function profileUniqueAccount(bytes32 profileId, uint256 index)
        external
        view
        returns (address account, uint32 sharePpm);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Original fixed-price and custody-auction paid receipts, distinct from universal settlement.
library StreamDirectPrimarySaleTypes {
    bytes32 internal constant MODULE_TYPE = keccak256("DIRECT_PRIMARY_SALE_ADAPTER");
    bytes32 internal constant MODULE_VERSION = keccak256("6529STREAM_DIRECT_PRIMARY_SALE_V1");
    bytes32 internal constant NATIVE_FIXED_PRICE =
        keccak256("6529STREAM_DIRECT_NATIVE_FIXED_PRICE_V1");
    bytes32 internal constant ERC20_FIXED_PRICE =
        keccak256("6529STREAM_DIRECT_ERC20_FIXED_PRICE_V1");
    bytes32 internal constant ENGLISH_AUCTION = keccak256("6529STREAM_DIRECT_ENGLISH_AUCTION_V1");

    /// @notice Immutable deployment identity of the original product that retains the receipt.
    struct Bindings {
        address core;
        bytes32 coreCodeHash;
        address mintManager;
        bytes32 mintManagerCodeHash;
        uint256 deploymentChainId;
        bytes32 productKind;
    }

    /// @notice Complete actual paid outcome keyed by the product's original authorizationId.
    /// @dev The authorization digest retains its original native, ERC20 or auction EIP-712 domain.
    /// For an auction, mint identities and admission time/revision are retained from creation;
    /// payer, beneficiary, amount and escrowed describe its later successful paid settlement.
    /// Unknown, unpaid, no-bid, cancelled and refunded operations return the all-zero tuple.
    /// The sixteen-word ABI occupies thirteen storage words through address/uint64/bool packing.
    struct Receipt {
        bytes32 authorizationDigest;
        uint256 collectionId;
        uint256 tokenId;
        bytes32 operationRoot;
        bytes32 operationId;
        bytes32 boundMintPolicyHash;
        bytes32 expectedPrimaryPolicyHash;
        bytes32 profileId;
        address wallet;
        uint64 createdAt;
        bool escrowed;
        address payer;
        uint64 registryRevision;
        address beneficiary;
        address asset;
        uint256 amount;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Typed universal primary settlement transcript. Numeric modes are explicit,
///         and implementations must reject modes they do not implement.
library StreamPrimarySettlementTypes {
    uint8 internal constant PRE_REVENUE_SINGLE_STEP = 1;
    uint8 internal constant AUTHORITY_SIGNED = 1;

    struct PrimarySale {
        bytes32 settlementId;
        bytes32 revenueClass;
        uint8 policyMode;
        uint256 collectionId;
        uint256 tokenId;
        uint256 saleNonce;
        address payer;
        address poster;
        address beneficiary;
        uint256 amount;
        bytes32 expectedPrimaryPolicyHash;
    }

    struct SaleLifecycleBinding {
        address paymentAdapter;
        uint64 saleCreatedAt;
        uint64 saleAdapterRegistryRevision;
        uint64 paymentAdapterRegistryRevision;
    }

    struct SaleExecutionBinding {
        bytes32 executionId;
        uint256 executionNonce;
        uint8 authorityMode;
        bytes32 saleAuthorizationDigest;
    }

    /// @dev These are resolver-derived concrete rights, not a caller-selected destination.
    struct PrimaryRights {
        bytes32 profileId;
        address wallet;
        bytes32 templateId;
        bytes32 assignmentHash;
        bytes32 entriesHash;
    }

    struct ERC20SettlementCandidate {
        address saleAdapter;
        address executor;
        PrimarySale sale;
        SaleLifecycleBinding lifecycleBinding;
        SaleExecutionBinding executionBinding;
        address asset;
        uint8 orchestrationOrder;
        address mintManager;
        bytes32 operationIdentityCommitment;
        bytes32 operationId;
        bytes32 currentPolicyHash;
        bytes32 boundPolicyHash;
        PrimaryRights rights;
        bytes32 saleExecutionHash;
    }

    /// @dev Exactly twelve ABI words (384 bytes). The sale callback adds a magic word,
    ///      for an exact 416-byte response. The single operation ID stays candidate-bound.
    struct PrimarySettlementResult {
        bytes32 candidateCommitment;
        bytes32 settlementKey;
        bytes32 profileId;
        address wallet;
        address asset;
        uint256 amount;
        address executor;
        bytes32 executionId;
        bool escrowed;
        bytes32 operationIdentityCommitment;
        bytes32 currentPolicyHash;
        bytes32 boundPolicyHash;
    }

    struct PaymentIntent {
        address payer;
        address asset;
        uint256 maxAmount;
        bytes32 saleRef;
        bytes32 expectedPrimaryPolicyHash;
        bytes32 nonce;
        uint64 deadline;
    }

    struct PaymentIntentRevocation {
        address payer;
        bytes32 nonce;
        uint64 deadline;
    }

    struct EIP2612PermitAuthorization {
        uint256 deadline;
        uint8 v;
        bytes32 r;
        bytes32 s;
    }

    struct Permit2TransferAuthorization {
        uint256 nonce;
        uint256 deadline;
        bytes signature;
    }
}

